theorem na_FinRun_of_FinRun' [Inhabited A] {n : ℕ} {as : Fin n → A} {ss : Fin (n + 1) → M.State}
    (h : M.FinRun' n as ss) : M.FinRun n (fun k ↦ if h : k < n then as ⟨k, h⟩ else default)
      (fun k ↦ if h : k < n + 1 then ss ⟨k, h⟩ else ss 0)

theorem extract_eq_extract {xs xs' : Stream' X} {m n m' n' : ℕ}
    (h : xs.extract m n = xs'.extract m' n') :
    n - m = n' - m' ∧ ∀ k < n - m, xs (m + k) = xs' (m' + k)
